CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE,phone text UNIQUE,google_sub text UNIQUE,name text NOT NULL DEFAULT '',password_hash text,platform_role text CHECK(platform_role IN ('founder','operations','catalog','support','finance','marketing')),disabled boolean NOT NULL DEFAULT false,totp_cipher text,pending_totp_cipher text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),token_hash text UNIQUE NOT NULL,csrf text NOT NULL,audience text NOT NULL CHECK(audience IN ('admin','partner','mobile')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_challenges(token_hash text PRIMARY KEY,user_id uuid REFERENCES users(id),kind text NOT NULL,context jsonb NOT NULL DEFAULT '{}',expires_at timestamptz NOT NULL,attempts int NOT NULL DEFAULT 0);
CREATE TABLE resources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL,name text NOT NULL,organization_id uuid REFERENCES resources(id),owner_id uuid REFERENCES users(id),status text NOT NULL DEFAULT 'draft',data jsonb NOT NULL DEFAULT '{}',version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX resources_kind_status ON resources(kind,status) WHERE deleted_at IS NULL;
CREATE INDEX resources_organization ON resources(organization_id) WHERE deleted_at IS NULL;
CREATE TABLE memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),organization_id uuid NOT NULL REFERENCES resources(id),role text NOT NULL CHECK(role IN ('owner','manager','cashier','scanner','marketing','accountant')),scopes uuid[] NOT NULL DEFAULT '{}',UNIQUE(user_id,organization_id));
CREATE TABLE invitations(token_hash text PRIMARY KEY,email text NOT NULL,organization_id uuid REFERENCES resources(id),role text NOT NULL,scopes uuid[] NOT NULL DEFAULT '{}',expires_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE media_assets(id uuid PRIMARY KEY,organization_id uuid REFERENCES resources(id),created_by uuid NOT NULL REFERENCES users(id),storage_key text UNIQUE NOT NULL,original_name text NOT NULL,mime text NOT NULL,bytes bigint NOT NULL,checksum text NOT NULL,visibility text NOT NULL CHECK(visibility IN ('public','private')),purpose text NOT NULL CHECK(purpose IN ('poster','identity','business_proof','venue_proof','agreement','tax','other')),created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE venue_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid UNIQUE REFERENCES resources(id),show_id uuid UNIQUE REFERENCES resources(id),space_id uuid NOT NULL REFERENCES resources(id),during tstzrange NOT NULL,EXCLUDE USING gist(space_id WITH =,during WITH &&));
CREATE TABLE inventory(show_id uuid NOT NULL REFERENCES resources(id),key text NOT NULL,label text NOT NULL,capacity int NOT NULL CHECK(capacity>0),sold int NOT NULL DEFAULT 0 CHECK(sold>=0 AND sold<=capacity),blocked boolean NOT NULL DEFAULT false,price_minor bigint NOT NULL CHECK(price_minor>=0),PRIMARY KEY(show_id,key));
CREATE TABLE holds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),show_id uuid NOT NULL REFERENCES resources(id),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','converted','expired','released')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hold_items(hold_id uuid NOT NULL REFERENCES holds(id),show_id uuid NOT NULL,key text NOT NULL,quantity int NOT NULL CHECK(quantity>0),price_minor bigint NOT NULL,PRIMARY KEY(hold_id,key),FOREIGN KEY(show_id,key) REFERENCES inventory(show_id,key));
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),organization_id uuid NOT NULL REFERENCES resources(id),show_id uuid NOT NULL REFERENCES resources(id),hold_id uuid UNIQUE NOT NULL REFERENCES holds(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','cancelled','refund_pending','refunded','payment_review')),amount_minor bigint NOT NULL,fee_minor bigint NOT NULL,commission_minor bigint NOT NULL,owner_minor bigint NOT NULL,currency text NOT NULL DEFAULT 'INR',snapshot jsonb NOT NULL,provider_order_id text UNIQUE,provider_payment_id text UNIQUE,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key));
CREATE TABLE tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),key text NOT NULL,label text NOT NULL,ordinal int NOT NULL,token_hash text UNIQUE NOT NULL,token_cipher text NOT NULL,status text NOT NULL DEFAULT 'valid' CHECK(status IN ('valid','checked_in','revoked')),checked_in_at timestamptz,checked_in_by uuid REFERENCES users(id),UNIQUE(order_id,key,ordinal));
CREATE TABLE provider_events(event_id text PRIMARY KEY,payload_hash text NOT NULL,processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid UNIQUE NOT NULL REFERENCES orders(id),reason text NOT NULL,status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','processing','processed','rejected','review')),approved_by uuid REFERENCES users(id),provider_refund_id text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES resources(id),order_id uuid REFERENCES orders(id),operation_key text UNIQUE NOT NULL,kind text NOT NULL,amount_minor bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bank_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES resources(id),holder text NOT NULL,ifsc text NOT NULL,account_cipher text NOT NULL,last4 text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),approved_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_approved_bank ON bank_accounts(organization_id) WHERE status='approved';
CREATE TABLE payouts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES resources(id),bank_id uuid NOT NULL REFERENCES bank_accounts(id),amount_minor bigint NOT NULL CHECK(amount_minor>0),status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','paid','rejected')),approved_by uuid REFERENCES users(id),transfer_reference text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE favourites(user_id uuid REFERENCES users(id),resource_id uuid REFERENCES resources(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,resource_id));
CREATE TABLE notification_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES orders(id),channel text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','sent','skipped','failed')),payload jsonb NOT NULL,attempts int NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,result text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,channel));
CREATE TABLE audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,resource_id uuid,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE consent_records(user_id uuid PRIMARY KEY REFERENCES users(id),marketing_sms boolean NOT NULL DEFAULT false,marketing_whatsapp boolean NOT NULL DEFAULT false,location boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
